//! The HIP-3 coins' external perps (hyperliquid-trade design 000664 §1): `server/data/hip3_external_sources.json`, the
//! one authority of which Binance `TRADIFI_PERPETUAL` contract is a HIP-3 coin's, generated by
//! `scripts/discover_hip3_external_sources.py` (an exact base-asset match, or a reviewed alias, each checked against
//! the coin's HL mark), reviewed coin by coin and embedded at build time: a coin outside it has no external quote,
//! never a guessed one.

use std::collections::BTreeMap;

use serde::Deserialize;

use crate::local_marks::{price::VenuePrice, sources::FeedMarkets};

const EMBEDDED: &str = include_str!("../../../data/hip3_external_sources.json");
/// The only venue the file may name.
const VENUE: &str = "binance_perp";

#[derive(Deserialize)]
struct SourcesFile {
    venue: String,
    coins: BTreeMap<String, Entry>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Entry {
    symbol: String,
    px_multiplier: String,
}

/// The external feed's markets: one per coin, in coin order, each with its multiplier (HL price = multiplier × Binance
/// price).
#[derive(Debug)]
pub(crate) struct Hip3ExternalSources {
    pub(crate) markets: FeedMarkets,
}

impl Hip3ExternalSources {
    pub(crate) fn embedded() -> Result<Self, String> {
        Self::parse(EMBEDDED)
    }

    /// A coin is `dex:NAME`, its symbol non-empty and listed once, its multiplier positive; the file lists at least
    /// one.
    pub(crate) fn parse(text: &str) -> Result<Self, String> {
        let file: SourcesFile = serde_json::from_str(text).map_err(|err| format!("HIP-3 external sources: {err}"))?;
        if file.venue != VENUE {
            return Err(format!("HIP-3 external sources: venue {:?}, not {VENUE:?}", file.venue));
        }
        let mut markets = FeedMarkets::default();
        for (coin, entry) in file.coins {
            let multiplier = VenuePrice::parse(&entry.px_multiplier).map_err(|err| format!("HIP-3 external sources: {coin}: {err}"))?;
            let named = coin.split_once(':').is_some_and(|(dex, name)| !dex.is_empty() && !name.is_empty());
            if !named || entry.symbol.is_empty() || !multiplier.is_positive() {
                return Err(format!("HIP-3 external sources: invalid listing {coin:?} -> {:?} × {multiplier}", entry.symbol));
            }
            markets.push(entry.symbol.clone(), coin.clone(), multiplier).map_err(|previous| {
                format!("HIP-3 external sources: symbol {} listed for {previous} and {coin}", entry.symbol)
            })?;
        }
        if markets.symbols.is_empty() {
            return Err("HIP-3 external sources list no coin".to_string());
        }
        Ok(Self { markets })
    }

    /// The coins, in the markets' order.
    pub(crate) fn coins(&self) -> impl Iterator<Item = &str> {
        self.markets.coins.iter().map(|(coin, _)| coin.as_str())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn one(coins: &str) -> String {
        format!(r#"{{"venue": "binance_perp", "coins": {coins}}}"#)
    }

    #[test]
    fn the_sources_are_checked_when_loaded() {
        let text = one(r#"{"xyz:TSLA": {"symbol": "TSLAUSDT", "pxMultiplier": "1"}, "xyz:GOLD": {"symbol": "XAUUSDT", "pxMultiplier": "1"}}"#);
        let sources = Hip3ExternalSources::parse(&text).unwrap();
        assert_eq!(sources.coins().collect::<Vec<_>>(), ["xyz:GOLD", "xyz:TSLA"]);
        assert_eq!(sources.markets.index("TSLAUSDT"), Some(1));
        let cases = [
            (r#"{"venue": "okx_perp", "coins": {"xyz:TSLA": {"symbol": "TSLAUSDT", "pxMultiplier": "1"}}}"#.to_string(), "not \"binance_perp\""),
            (one(r#"{"TSLA": {"symbol": "TSLAUSDT", "pxMultiplier": "1"}}"#), "invalid listing"),
            (one(r#"{"xyz:": {"symbol": "TSLAUSDT", "pxMultiplier": "1"}}"#), "invalid listing"),
            (one(r#"{"xyz:TSLA": {"symbol": "", "pxMultiplier": "1"}}"#), "invalid listing"),
            (one(r#"{"xyz:TSLA": {"symbol": "TSLAUSDT", "pxMultiplier": "0"}}"#), "invalid listing"),
            (one(r#"{"xyz:TSLA": {"symbol": "TSLAUSDT"}}"#), "missing field `pxMultiplier`"),
            (one(r#"{"xyz:TSLA": {"symbol": "TSLAUSDT", "pxMultiplier": "1"}, "abc:TSLA": {"symbol": "TSLAUSDT", "pxMultiplier": "1"}}"#), "listed for abc:TSLA and xyz:TSLA"),
            (one("{}"), "list no coin"),
        ];
        for (text, message) in cases {
            let error = Hip3ExternalSources::parse(&text).unwrap_err();
            assert!(error.contains(message), "{error}");
        }
    }

    /// The discovery run of 11-02 09:07Z on bm: 92 of xyz's 120 perps, 85 by their exact name and the 7 reviewed
    /// aliases; GIGADEV (+3.9%) and UNITREE (+1.1%) off HL's mark, KIOXIA and the indices without a Binance perp.
    #[test]
    fn the_embedded_sources_list_the_reviewed_coins() {
        let sources = Hip3ExternalSources::embedded().unwrap();
        let coins: Vec<&str> = sources.coins().collect();
        assert_eq!(coins.len(), 92);
        let symbol = |coin: &str| sources.markets.coins.iter().position(|(each, _)| each == coin).map(|index| sources.markets.symbols[index].as_str());
        assert_eq!((symbol("xyz:TSLA"), symbol("xyz:KORU"), symbol("xyz:GOLD"), symbol("xyz:SKHX")), (Some("TSLAUSDT"), Some("KORUUSDT"), Some("XAUUSDT"), Some("SKHYNIXUSDT")));
        assert!(["xyz:KIOXIA", "xyz:GIGADEV", "xyz:UNITREE", "xyz:SP500", "xyz:ANT"].iter().all(|coin| !coins.contains(coin)));
    }
}
